import { useContext } from 'react';
import { AuthContext } from '../../context/authContext';
import { DarkModeContext } from '../../context/darkModeContext';
import './friends.scss';

const Friends = () => {
  const { currentUser } = useContext(AuthContext);
  const { darkMode } = useContext(DarkModeContext);

  if (!currentUser) {
    return null;
  }

  // Mock friends data (replace with API)
  const friends = [
    {
      id: 1,
      name: "John Doe",
      profilePic: "https://images.pexels.com/photos/1036623/pexels-photo-1036623.jpeg?auto=compress&cs=tinysrgb&w=1600",
    },
    {
      id: 2,
      name: "Jane Doe",
      profilePic: "https://images.pexels.com/photos/1036623/pexels-photo-1036623.jpeg?auto=compress&cs=tinysrgb&w=1600",
    },
  ];

  return (
    <div className={`friends ${darkMode ? 'theme-dark' : 'theme-light'}`}>
      <h2>{currentUser.name}'s Friends</h2>
      <div className="friends-list">
        {friends.length > 0 ? (
          friends.map(friend => (
            <div key={friend.id} className="friend-card">
              <img src={friend.profilePic} alt={friend.name} className="avatar" />
              <span>{friend.name}</span>
            </div>
          ))
        ) : (
          <p>No friends found.</p>
        )}
      </div>
    </div>
  );
};

export default Friends;
